const text = String($input.first().json.text || "").trim();
const metrics = $("When Called by Supervisor").first().json.metrics || {};
if (!text) {
  throw new Error("Executive Reporting Agent: model returned empty text");
}
const words = text.split(/\s+/).filter(Boolean).length;
if (words > 180) {
  throw new Error("Executive Reporting Agent: report exceeds 180 words (" + words + ")");
}
const lower = text.toLowerCase();
const missing = ["Headline", "Key Metrics", "Risks and Opportunities", "Priority Actions"].filter((s) => !lower.includes(s.toLowerCase()));
if (missing.length) {
  throw new Error("Executive Reporting Agent: missing sections: " + missing.join(", "));
}
const norm = (s) => String(parseFloat(String(s).replace(/,/g, "")));
const allowed = new Set((JSON.stringify(metrics).match(/\d+(?:[.,]\d+)*/g) || []).map(norm));
const used = (text.match(/\d+(?:[.,]\d+)*/g) || []).map(norm);
const unknown = [...new Set(used.filter((n) => !allowed.has(n)))];
if (unknown.length) {
  throw new Error("Executive Reporting Agent: figures not present in supplied metrics: " + unknown.join(", "));
}
return [{ json: { text } }];
